mapper.select:
SELECT od.overseas_order_no AS overseasOrderNo, COUNT(DISTINCT od.sku) AS productCount, CAST(IFNULL(MAX(od.order_total_box_num), SUM(GREATEST(IFNULL(od.box_number, 0), 0))) AS SIGNED) AS totalBoxCount, SUM(GREATEST(IFNULL(od.quantity_in_case, 1), 1) * GREATEST(IFNULL(od.box_number, 1), 1)) AS totalQuantity, IFNULL(MAX(od.order_total_box_weight), SUM(IFNULL(od.cg_box_weight, 0) * GREATEST(IFNULL(od.box_number, 1), 1))) AS totalGrossWeight FROM overseas_stock_order_detail od WHERE od.overseas_order_no IS NOT NULL AND od.overseas_order_no != ''
AND od.overseas_order_no LIKE CONCAT('%', #{keyword}, '%')
GROUP BY od.overseas_order_no ORDER BY od.overseas_order_no DESC LIMIT #{limit}

SELECT t.shipment_id AS shipmentId, SUM(t.productCount) AS productCount, MAX(t.totalBoxCount) AS totalBoxCount, SUM(t.totalQuantity) AS totalQuantity, SUM(t.totalGrossWeight) AS totalGrossWeight FROM ( SELECT b.shipment_id, COUNT(DISTINCT b.sku) AS productCount, MAX(b.box_num) AS totalBoxCount, SUM(IF(b.quantity_in_case IS NOT NULL AND b.quantity_in_case REGEXP '^[0-9.]+$', CAST(b.quantity_in_case AS DECIMAL(12,4)), 1)) * MAX(GREATEST(IFNULL(b.box_num, 1), 1)) AS totalQuantity, MAX(IF(b.box_weight IS NOT NULL AND b.box_weight REGEXP '^[0-9.]+$', CAST(b.box_weight AS DECIMAL(12,4)) * IF(UPPER(IFNULL(b.box_weight_unit, 'KG')) IN ('LB', 'LBS'), 0.45359237, 1), 0)) * MAX(GREATEST(IFNULL(b.box_num, 1), 1)) AS totalGrossWeight FROM amz_fba_shipment_box b WHERE b.shipment_id IS NOT NULL AND b.shipment_id != ''
AND b.shipment_id LIKE CONCAT('%', #{keyword}, '%')
GROUP BY b.shipment_id, b.box_num, b.box_weight, COALESCE(b.box_length,''), COALESCE(b.box_width,''), COALESCE(b.box_height,'') ) t GROUP BY t.shipment_id ORDER BY MAX(t.shipment_id) DESC LIMIT #{limit}

SELECT , CAST(IF(b.quantity_in_case IS NOT NULL AND b.quantity_in_case REGEXP '^[0-9.]+$', CAST(b.quantity_in_case AS DECIMAL(12,4)), 1) * GREATEST(IFNULL(b.box_num, 1), 1) AS SIGNED) AS quantity, CAST(GREATEST(IFNULL(b.box_num, 1), 1) AS SIGNED) AS box_count, b.shipment_id AS source_order_no, 'FBA' AS declaration_source_type, CAST(b.id AS CHAR) AS source_line_id, b.sku AS raw_sku, CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN 'FBA_DE' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN 'FBA_UK' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN 'FBA_US' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN 'FBA_FR' ELSE 'UNKNOWN' END AS warehouse_bucket, COALESCE(CONCAT('FBA(', s.ship_to_country_code, ')'), 'FBA未知仓') AS warehouse_name, CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('DE', 'UK', 'GB', 'US', 'FR') THEN 'MATCHED' ELSE 'UNKNOWN_WAREHOUSE' END AS match_status, b.box_no AS box_no, IF(b.box_weight REGEXP '^[0-9.]+$', CAST(b.box_weight AS DECIMAL(12,4)) * IF(UPPER(IFNULL(b.box_weight_unit, 'KG')) IN ('LB', 'LBS'), 0.45359237, 1), p.packing_gross_weight) AS packing_gross_weight, IF(b.box_length REGEXP '^[0-9.]+$', CAST(b.box_length AS DECIMAL(12,4)) * IF(UPPER(IFNULL(b.box_dimensions_unit, 'CM')) IN ('IN', 'INCH'), 2.54, 1), p.box_length) AS box_length, IF(b.box_width REGEXP '^[0-9.]+$', CAST(b.box_width AS DECIMAL(12,4)) * IF(UPPER(IFNULL(b.box_dimensions_unit, 'CM')) IN ('IN', 'INCH'), 2.54, 1), p.box_width) AS box_width, IF(b.box_height REGEXP '^[0-9.]+$', CAST(b.box_height AS DECIMAL(12,4)) * IF(UPPER(IFNULL(b.box_dimensions_unit, 'CM')) IN ('IN', 'INCH'), 2.54, 1), p.box_height) AS box_height, COALESCE( IF(b.box_volume REGEXP '^[0-9.]+$', CAST(b.box_volume AS DECIMAL(12,6)), NULL), IF(b.box_length REGEXP '^[0-9.]+$' AND b.box_width REGEXP '^[0-9.]+$' AND b.box_height REGEXP '^[0-9.]+$', CAST(b.box_length AS DECIMAL(12,4)) * CAST(b.box_width AS DECIMAL(12,4)) * CAST(b.box_height AS DECIMAL(12,4)) * POW(IF(UPPER(IFNULL(b.box_dimensions_unit, 'CM')) IN ('IN', 'INCH'), 2.54, 1), 3) / 1000000, p.packing_cbm) ) AS packing_cbm FROM amz_fba_shipment_box b LEFT JOIN ( SELECT shipment_id, MAX(ship_to_country_code) AS ship_to_country_code FROM amz_fba_shipment GROUP BY shipment_id ) s ON s.shipment_id COLLATE utf8mb4_unicode_ci = b.shipment_id COLLATE utf8mb4_unicode_ci LEFT JOIN customs_inventory_list il ON il.id = ( SELECT i2.id FROM customs_inventory_list i2 WHERE i2.sku IS NOT NULL AND i2.sku != '' AND normalize_customs_sku_key(i2.sku) COLLATE utf8mb4_unicode_ci = normalize_customs_sku_key(b.sku) COLLATE utf8mb4_unicode_ci ORDER BY CASE WHEN UPPER(i2.sku) LIKE 'JMH%' AND ( CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN COALESCE(i2.auto_fba_de_qty, i2.fba_de_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN COALESCE(i2.auto_fba_uk_qty, i2.fba_uk_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN COALESCE(i2.auto_fba_us_qty, i2.fba_us_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN COALESCE(i2.auto_fba_fr_qty, i2.fba_fr_qty, 0) ELSE COALESCE(i2.auto_remaining_stock, i2.remaining_stock, 0) END - COALESCE(( SELECT SUM(l.quantity) FROM customs_declaration_generate_log l WHERE l.standard_sku COLLATE utf8mb4_unicode_ci = i2.sku COLLATE utf8mb4_unicode_ci AND IFNULL(l.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(i2.product_code, '') COLLATE utf8mb4_unicode_ci AND l.warehouse_bucket COLLATE utf8mb4_unicode_ci = (CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN 'FBA_DE' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN 'FBA_UK' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN 'FBA_US' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN 'FBA_FR' ELSE 'UNKNOWN' END) COLLATE utf8mb4_unicode_ci ), 0) ) > 0 THEN 0 WHEN UPPER(i2.sku) NOT LIKE 'JMH%' AND ( CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN COALESCE(i2.auto_fba_de_qty, i2.fba_de_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN COALESCE(i2.auto_fba_uk_qty, i2.fba_uk_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN COALESCE(i2.auto_fba_us_qty, i2.fba_us_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN COALESCE(i2.auto_fba_fr_qty, i2.fba_fr_qty, 0) ELSE COALESCE(i2.auto_remaining_stock, i2.remaining_stock, 0) END - COALESCE(( SELECT SUM(l.quantity) FROM customs_declaration_generate_log l WHERE l.standard_sku COLLATE utf8mb4_unicode_ci = i2.sku COLLATE utf8mb4_unicode_ci AND IFNULL(l.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(i2.product_code, '') COLLATE utf8mb4_unicode_ci AND l.warehouse_bucket COLLATE utf8mb4_unicode_ci = (CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN 'FBA_DE' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN 'FBA_UK' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN 'FBA_US' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN 'FBA_FR' ELSE 'UNKNOWN' END) COLLATE utf8mb4_unicode_ci ), 0) ) > 0 THEN 1 WHEN UPPER(i2.sku) LIKE 'JMH%' THEN 2 ELSE 3 END, i2.id LIMIT 1 ) INNER JOIN customs_declaration_product_view p ON ((il.sku IS NOT NULL AND p.sku COLLATE utf8mb4_unicode_ci = il.sku COLLATE utf8mb4_unicode_ci AND IFNULL(p.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(il.product_code, '') COLLATE utf8mb4_unicode_ci) OR (il.sku IS NULL AND p.sku_key COLLATE utf8mb4_unicode_ci = normalize_customs_sku_key(b.sku) COLLATE utf8mb4_unicode_ci)) WHERE b.shipment_id IN #{shipment}
AND CONCAT(b.shipment_id, '|', b.sku) IN #{skuKey}
ORDER BY FIELD(b.shipment_id, #{shipment} ), b.id

SELECT DISTINCT b.sku FROM amz_fba_shipment_box b LEFT JOIN ( SELECT shipment_id, MAX(ship_to_country_code) AS ship_to_country_code FROM amz_fba_shipment GROUP BY shipment_id ) s ON s.shipment_id COLLATE utf8mb4_unicode_ci = b.shipment_id COLLATE utf8mb4_unicode_ci LEFT JOIN customs_inventory_list il ON il.id = ( SELECT i2.id FROM customs_inventory_list i2 WHERE i2.sku IS NOT NULL AND i2.sku != '' AND normalize_customs_sku_key(i2.sku) COLLATE utf8mb4_unicode_ci = normalize_customs_sku_key(b.sku) COLLATE utf8mb4_unicode_ci ORDER BY CASE WHEN UPPER(i2.sku) LIKE 'JMH%' AND ( CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN COALESCE(i2.auto_fba_de_qty, i2.fba_de_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN COALESCE(i2.auto_fba_uk_qty, i2.fba_uk_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN COALESCE(i2.auto_fba_us_qty, i2.fba_us_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN COALESCE(i2.auto_fba_fr_qty, i2.fba_fr_qty, 0) ELSE COALESCE(i2.auto_remaining_stock, i2.remaining_stock, 0) END - COALESCE(( SELECT SUM(l.quantity) FROM customs_declaration_generate_log l WHERE l.standard_sku COLLATE utf8mb4_unicode_ci = i2.sku COLLATE utf8mb4_unicode_ci AND IFNULL(l.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(i2.product_code, '') COLLATE utf8mb4_unicode_ci AND l.warehouse_bucket COLLATE utf8mb4_unicode_ci = (CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN 'FBA_DE' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN 'FBA_UK' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN 'FBA_US' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN 'FBA_FR' ELSE 'UNKNOWN' END) COLLATE utf8mb4_unicode_ci ), 0) ) > 0 THEN 0 WHEN UPPER(i2.sku) NOT LIKE 'JMH%' AND ( CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN COALESCE(i2.auto_fba_de_qty, i2.fba_de_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN COALESCE(i2.auto_fba_uk_qty, i2.fba_uk_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN COALESCE(i2.auto_fba_us_qty, i2.fba_us_qty, 0) WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN COALESCE(i2.auto_fba_fr_qty, i2.fba_fr_qty, 0) ELSE COALESCE(i2.auto_remaining_stock, i2.remaining_stock, 0) END - COALESCE(( SELECT SUM(l.quantity) FROM customs_declaration_generate_log l WHERE l.standard_sku COLLATE utf8mb4_unicode_ci = i2.sku COLLATE utf8mb4_unicode_ci AND IFNULL(l.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(i2.product_code, '') COLLATE utf8mb4_unicode_ci AND l.warehouse_bucket COLLATE utf8mb4_unicode_ci = (CASE WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'DE' THEN 'FBA_DE' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci IN ('UK', 'GB') THEN 'FBA_UK' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'US' THEN 'FBA_US' WHEN UPPER(IFNULL(s.ship_to_country_code, '')) COLLATE utf8mb4_unicode_ci = 'FR' THEN 'FBA_FR' ELSE 'UNKNOWN' END) COLLATE utf8mb4_unicode_ci ), 0) ) > 0 THEN 1 WHEN UPPER(i2.sku) LIKE 'JMH%' THEN 2 ELSE 3 END, i2.id LIMIT 1 ) LEFT JOIN customs_declaration_product_view p ON ((il.sku IS NOT NULL AND p.sku COLLATE utf8mb4_unicode_ci = il.sku COLLATE utf8mb4_unicode_ci AND IFNULL(p.product_code, '') COLLATE utf8mb4_unicode_ci = IFNULL(il.product_code, '') COLLATE utf8mb4_unicode_ci) OR (il.sku IS NULL AND p.sku_key COLLATE utf8mb4_unicode_ci = normalize_customs_sku_key(b.sku) COLLATE utf8mb4_unicode_ci)) WHERE b.shipment_id IN #{shipment}
AND CONCAT(b.shipment_id, '|', b.sku) IN #{skuKey}
AND b.sku IS NOT NULL AND b.sku != '' AND p.sku IS NULL ORDER BY b.sku

SELECT DISTINCT b.sku FROM amz_fba_shipment_box b LEFT JOIN ( SELECT match_key FROM ( SELECT normalize_customs_sku_key(sku) AS match_key, ROW_NUMBER() OVER (PARTITION BY normalize_customs_sku_key(sku) ORDER BY id) AS rn FROM customs_inventory_list WHERE sku IS NOT NULL AND sku != '' ) ranked WHERE rn = 1 ) il ON normalize_customs_sku_key(b.sku) COLLATE utf8mb4_unicode_ci = il.match_key COLLATE utf8mb4_unicode_ci WHERE b.shipment_id IN #{shipment}
AND CONCAT(b.shipment_id, '|', b.sku) IN #{skuKey}
AND b.sku IS NOT NULL AND b.sku != '' AND il.match_key IS NULL ORDER BY b.sku
